input.command:
cd "$INPUT_DIR" && for f in *.pptx; do echo "=== $f"; python3 -c "
from pptx import Presentation
import sys
p=Presentation(sys.argv[1])
for i,s in enumerate(p.slides,1):
    for sh in s.shapes:
        if sh.has_text_frame and 'ustomer' in sh.text_frame.text:
            print(i, sh.text_frame.text[:400])
        if sh.has_table:
            for r in sh.table.rows:
                t=' | '.join(c.text for c in r.cells)
                if 'ustomer' in t: print(i,t)
" "$f"; done
echo "=== xlsx scan"
python3 -c "
import openpyxl,glob
for f in sorted(glob.glob('*.xlsx')):
    wb=openpyxl.load_workbook(f)
    for ws in wb:
        for row in ws.iter_rows():
            for c in row:
                if isinstance(c.value,str) and 'ustomer' in c.value:
                    print(f,ws.title,c.coordinate,c.value[:200])
"
